function main(config) {
  if (!config.proxies) config.proxies = [];

  config.ipv6 = false;
  if (!config["proxy-groups"]) config["proxy-groups"] = [];

  config["rule-providers"] = {};

  const NODIRECT = "^((?!(直连|DIRECT)).)*$";
  const NOJUNK = "剩余|流量|到期|过期|官网|订阅|重置|续费|Traffic|Expire|GB";

  function rateOf(name) {
    var m = String(name || "").match(/(?:^|[^\d.])(0\.\d*[1-9])/);
    return m ? parseFloat(m[1]) : null;
  }

  function sortedByRate(names) {
    return names.slice().sort(function (a, b) {
      var ra = rateOf(a), rb = rateOf(b);
      if (ra === null && rb === null) return 0;
      if (ra === null) return 1;
      if (rb === null) return -1;
      if (ra !== rb) return ra - rb;
      return 0;
    });
  }

  const HC_URL = "https://www.gstatic.com/generate_204";
  const HC_INT = 300;

  const ICON = "https://raw.githubusercontent.com/RiverFlowsInUUU/self-conf/main/icons/";
  const RAW = "https://raw.githubusercontent.com/RiverFlowsInUUU/self-conf/main/";

  const HAS_PROVIDERS =
    config["proxy-providers"] && Object.keys(config["proxy-providers"]).length > 0;
  const ALL_KEY = HAS_PROVIDERS ? "include-all" : "include-all-proxies";
  const allNodes = {};
  allNodes[ALL_KEY] = true;

  var usable = (config.proxies || [])
    .map(function (p) { return p && p.name; })
    .filter(function (n) {
      if (!n) return false;
      if (!new RegExp(NODIRECT).test(n)) return false;
      if (new RegExp(NOJUNK).test(n)) return false;
      return true;
    });
  var smartOrder = sortedByRate(usable);

  config["proxy-groups"] = [
    {
      name: "Proxy",
      type: "select",
      proxies: [
        "Smart",
        "Hong Kong", "Taiwan", "Japan", "Singapore", "United States",
        "Other Regions",
      ],
      icon: ICON + "Proxy.png",
    },
    {
      name: "Smart",
      type: "fallback",
      proxies: smartOrder.length ? smartOrder : ["DIRECT"],
      url: HC_URL,
      interval: HC_INT,
      icon: ICON + "Auto.png",
    },

    {
      name: "ChatGPT",
      type: "select",
      proxies: ["United States", "Taiwan", "Japan", "Singapore"],
      icon: ICON + "openai.png",
    },
    {
      name: "Gemini",
      type: "select",
      proxies: ["United States", "Taiwan", "Japan", "Singapore"],
      icon: ICON + "gemini-color.png",
    },
    {
      name: "Claude",
      type: "select",
      proxies: ["Taiwan", "Japan", "Singapore", "United States"],
      icon: ICON + "claude-color.png",
    },

    {
      name: "AI",
      type: "select",
      proxies: ["Smart", "Taiwan", "Japan", "Singapore", "United States"],
      icon: ICON + "grok.png",
    },
    {
      name: "YouTube",
      type: "select",
      proxies: ["Smart", "Hong Kong", "Taiwan", "Japan", "Singapore", "United States"],
      icon: ICON + "YouTube.png",
    },

    {
      name: "Emby",
      type: "select",
      proxies: ["Smart", "Hong Kong", "Taiwan", "Japan", "Singapore", "United States"],
      icon: ICON + "Emby.png",
    },

    {
      name: "Google",
      type: "select",
      proxies: ["Gemini", "Smart", "Hong Kong", "Taiwan", "Japan", "Singapore", "United States"],
      icon: ICON + "Google.png",
    },

    {
      name: "Telegram",
      type: "select",
      proxies: ["Smart", "Hong Kong", "Taiwan", "Japan", "Singapore", "United States"],
      icon: ICON + "Telegram.png",
    },

    {
      name: "YouTube Music",
      type: "select",
      proxies: ["United States", "Hong Kong", "Taiwan", "Japan", "Singapore"],
      icon: ICON + "YouTubeMusic.png",
    },

    {
      name: "Spotify",
      type: "select",
      proxies: ["United States", "Hong Kong", "Taiwan", "Japan", "Singapore"],
      icon: ICON + "Spotify.png",
    },

    {
      name: "Twitter",
      type: "select",
      proxies: ["Smart", "Hong Kong", "Taiwan", "Japan", "Singapore", "United States"],
      icon: ICON + "Twitter.png",
    },

    {
      name: "Microsoft",
      type: "select",
      proxies: ["DIRECT", "Proxy"],
      icon: ICON + "Microsoft.png",
    },
    {
      name: "Apple Update",
      type: "select",
      proxies: ["DIRECT", "REJECT"],
      icon: ICON + "Apple.png",
    },

    {
      name: "AD",
      type: "select",
      proxies: ["REJECT", "DIRECT"],
      icon: ICON + "AdBlock.png",
    },

    {
      name: "Hong Kong",
      type: "url-test",
      ...allNodes,
      filter: "(?i)(?=.*(香港|港|HK|Hong))^((?!(台|日|韩|新|美)).)*$",
      url: HC_URL,
      interval: HC_INT,
      tolerance: 50,
      icon: ICON + "HongKong.png",
    },

    {
      name: "Taiwan",
      type: "url-test",
      ...allNodes,
      filter: "(?i)(?=.*(台湾|台|TW|Taiwan|Tai|TPE|Taipei))^((?!(港|韩|新|美|日)).)*$",
      url: HC_URL,
      interval: HC_INT,
      tolerance: 50,
      icon: ICON + "Taiwan.png",
    },

    {
      name: "Japan",
      type: "url-test",
      ...allNodes,
      filter: "(?i)(?=.*(日本|东京|大阪|日|JP|Japan|NRT|HND|KIX|FUK|NGO|OSA|CTS|SDJ|OKA))^((?!(港|台|韩|新|美)).)*$",
      url: HC_URL,
      interval: HC_INT,
      tolerance: 50,
      icon: ICON + "Japan.png",
    },

    {
      name: "Singapore",
      type: "url-test",
      ...allNodes,
      filter: "(?i)(?=.*(新加坡|坡|狮城|SG|SGP|SIN|Singapore))^((?!(台|日|韩|深|美)).)*$",
      url: HC_URL,
      interval: HC_INT,
      tolerance: 50,
      icon: ICON + "Singapore.png",
    },

    {
      name: "United States",
      type: "url-test",
      ...allNodes,
      filter: "(?i)(?=.*(美国|美|US|USA|United|States|America|洛杉矶|硅谷|西雅图|芝加哥|达拉斯|凤凰城|阿什本|纽约|迈阿密|波士顿|休斯顿|亚特兰大|拉斯维加斯|圣地亚哥|盐湖城|奥斯汀|波特兰|丹佛|奥克兰|安大略|圣安娜|LAX|SJC|SFO|SEA|ORD|JFK|DFW|IAD|PHX|ATL|BOS|MIA|EWR|LGA|IAH|HOU|DEN|OAK|ONT|SNA|LAS|PDX|DAL|SAN|SLC|MSP))^((?!(港|台|韩|新|日)).)*$",
      url: HC_URL,
      interval: HC_INT,
      tolerance: 50,
      icon: ICON + "UnitedStates.png",
    },

    {
      name: "Other Regions",
      type: "url-test",
      ...allNodes,
      filter: "(?i)^(?!(.*(香港|港|HK|Hong|台湾|台|TW|Taiwan|Tai|TPE|Taipei|日本|东京|大阪|日|JP|Japan|NRT|HND|KIX|FUK|NGO|OSA|CTS|SDJ|OKA|新加坡|坡|狮城|SG|Singapore|SIN|SGP|美国|美|US|United|States|America|USA|洛杉矶|硅谷|西雅图|芝加哥|达拉斯|凤凰城|阿什本|纽约|迈阿密|波士顿|休斯顿|亚特兰大|拉斯维加斯|圣地亚哥|盐湖城|奥斯汀|波特兰|丹佛|奥克兰|安大略|圣安娜|LAX|SJC|SFO|SEA|ORD|JFK|DFW|IAD|PHX|ATL|BOS|MIA|EWR|LGA|IAH|HOU|DEN|OAK|ONT|SNA|LAS|PDX|DAL|SAN|SLC|MSP)))(?!(.*(剩余|流量|到期|过期|官网|订阅|重置|续费|Traffic|Expire|GB|倍率|测试|有效|禁止|邮箱|客服|地址|网站|群组))).+$",
      url: HC_URL,
      interval: HC_INT,
      tolerance: 50,
      icon: ICON + "WorldMap.png",
    },
  ];

  const JS = "https://cdn.jsdelivr.net/gh/MetaCubeX/meta-rules-dat@meta/geo";
  const rp = config["rule-providers"];

  [
    "apple-update", "spotify", "private", "anthropic", "category-ai-chat-!cn",
    "github", "youtube", "google", "microsoft", "apple-cn", "telegram", "twitter",
    "cn", "openai", "google-gemini",
  ].forEach(function (c) {
    rp[c] = {
      type: "http",
      behavior: "domain",
      format: "mrs",
      url: JS + "/geosite/" + c + ".mrs",
      path: "./rule_provider/" + c + ".mrs",
      interval: 86400,
    };
  });

  ["private", "google", "telegram", "cn"].forEach(function (c) {
    rp["geoip-" + c] = {
      type: "http",
      behavior: "ipcidr",
      format: "mrs",
      url: JS + "/geoip/" + c + ".mrs",
      path: "./rule_provider/geoip-" + c + ".mrs",
      interval: 86400,
    };
  });

  rp["AWAvenue-Ads"] = {
    type: "http",
    behavior: "domain",
    format: "mrs",
    url: "https://raw.githubusercontent.com/TG-Twilight/AWAvenue-Ads-Rule/main/Filters/AWAvenue-Ads-Rule-Clash.mrs",
    path: "./rule_provider/AWAvenue-Ads-Rule-Clash.mrs",
    interval: 86400,
  };
  rp["Jinx-CN"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: "https://raw.githubusercontent.com/RiverFlowsInUUU/Jinx/main/mihomo-direct.yaml",
    path: "./rule_provider/Jinx-CN.yaml",
    interval: 86400,
  };
  rp["Jinx-Ads"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: "https://raw.githubusercontent.com/RiverFlowsInUUU/Jinx/main/mihomo-ads.yaml",
    path: "./rule_provider/Jinx-Ads.yaml",
    interval: 86400,
  };

  rp["emby"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: RAW + "rules/emby.yaml",
    path: "./rule_provider/emby.yaml",
    interval: 86400,
  };

  rp["AI_Domains"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: RAW + "rules/AI_Domains.yaml",
    path: "./rule_provider/AI_Domains.yaml",
    interval: 86400,
  };
  rp["apple-system"] = {
    type: "http",
    behavior: "classical",
    format: "yaml",
    url: RAW + "rules/apple_system.yaml",
    path: "./rule_provider/apple_system.yaml",
    interval: 86400,
  };

  config.rules = [
    "RULE-SET,Jinx-CN,DIRECT",
    "RULE-SET,Jinx-Ads,AD",
    "RULE-SET,AWAvenue-Ads,AD",
    "RULE-SET,apple-update,Apple Update",
    "RULE-SET,apple-system,DIRECT",
    "RULE-SET,geoip-private,DIRECT,no-resolve",
    "RULE-SET,private,DIRECT",
    "RULE-SET,openai,ChatGPT",
    "RULE-SET,google-gemini,Gemini",
    "RULE-SET,anthropic,Claude",
    "RULE-SET,category-ai-chat-!cn,AI",
    "RULE-SET,AI_Domains,AI",
    "DOMAIN-SUFFIX,music.youtube.com,YouTube Music",
    "RULE-SET,github,Proxy",
    "RULE-SET,youtube,YouTube",
    "RULE-SET,emby,Emby",
    "RULE-SET,google,Google",
    "RULE-SET,spotify,Spotify",
    "RULE-SET,twitter,Twitter",
    "RULE-SET,microsoft,Microsoft",
    "RULE-SET,apple-cn,DIRECT",
    "RULE-SET,telegram,Telegram",
    "RULE-SET,geoip-google,Google,no-resolve",
    "RULE-SET,geoip-telegram,Telegram,no-resolve",
    "RULE-SET,cn,DIRECT",
    "RULE-SET,geoip-cn,DIRECT,no-resolve",
    "MATCH,Proxy",
  ];

  config.dns = {
    enable: true,
    ipv6: false,
    "enhanced-mode": "fake-ip",
    "fake-ip-range": "198.18.0.1/16",
    "respect-rules": true,
    "use-hosts": true,
    "use-system-hosts": false,
    "prefer-h3": false,

    "default-nameserver": ["223.5.5.5", "119.29.29.29"],

    "direct-nameserver": [
      "https://doh.18bit.cn/dns-query",
      "https://dns.alidns.com/dns-query",
    ],
    "proxy-server-nameserver": [
      "https://doh.18bit.cn/dns-query",
      "https://dns.alidns.com/dns-query",
    ],

    nameserver: [
      "https://1.1.1.1/dns-query",
      "https://8.8.8.8/dns-query",
    ],
    fallback: [
      "https://1.1.1.1/dns-query",
      "https://8.8.8.8/dns-query",
    ],
    "fallback-filter": { geoip: true },

    "nameserver-policy": {
      "rule-set:AWAvenue-Ads": "rcode://success",
      "rule-set:Jinx-Ads": "rcode://success",
      "rule-set:private": [
        "https://doh.18bit.cn/dns-query",
        "https://dns.alidns.com/dns-query",
      ],
      "rule-set:cn": [
        "https://doh.18bit.cn/dns-query",
        "https://dns.alidns.com/dns-query",
      ],
    },

    "fake-ip-filter": [
      "*.lan",
      "*.local",
      "*.localdomain",
      "*.home.arpa",
      "+.msftconnecttest.com",
      "+.msftncsi.com",
      "localhost.ptlogin2.qq.com",
      "+.srv.nintendo.net",
      "+.stun.playstation.net",
      "+.xboxlive.com",
      "stun.*",
      "time.*.com",
      "ntp.*.com",
      "+.pool.ntp.org",
      "+.market.xiaomi.com",
      "rule-set:AWAvenue-Ads",
      "rule-set:Jinx-Ads",
    ],
  };

  return config;
}
